// Runs in a separate process: a microtask loop must fail a deadline, not hang CI.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {JSDOM,requestInterceptor,VirtualConsole}=require('jsdom');
const root=path.resolve(__dirname,'../..');
const version=require('../../release.json').version;
const seed=require('../harness.cjs')(true,true);
const saved=seed.run('S.done=7;S.coins=42;JSON.stringify(S)');
const errors=[],requests=[],registrations=[];
const resources={interceptors:[requestInterceptor(async request=>{
 const u=new URL(request.url);
 if(u.origin!=='https://mochi.test')return new Response('',{headers:{'Content-Type':'text/css'}});
 const file=path.join(root,u.pathname.replace('/app/',''));
 requests.push(u.pathname);
 return new Response(fs.readFileSync(file),{headers:{'Content-Type':file.endsWith('.js')?'application/javascript':'text/css'}});
})]};
const vc=new VirtualConsole();vc.on('jsdomError',e=>errors.push(e.message));
const dom=new JSDOM(fs.readFileSync(path.join(root,'index.html'),'utf8'),{
 url:'https://mochi.test/app/',runScripts:'dangerously',resources,pretendToBeVisual:true,virtualConsole:vc,
 beforeParse(w){
  w.HTMLCanvasElement.prototype.getContext=()=>null;
  w.HTMLElement.prototype.scrollIntoView=()=>{};
  w.matchMedia=()=>({matches:false,addEventListener(){},removeEventListener(){}});
  w.storage={get:()=>new Promise(()=>{}),set:()=>new Promise(()=>{})};
  w.localStorage.setItem('mochi-tutor-v1',saved);
  w.fetch=()=>new Promise(()=>{}); // No real cloud/AI requests. Deliberately never resolves.
  w.localStorage.setItem('cubs_sync',JSON.stringify({url:'https://example.firebaseio.com',code:'test-family'}));
  Object.defineProperty(w.navigator,'serviceWorker',{value:{register:async(url)=>{registrations.push(url);return {};}}});
 }
});
const w=dom.window,delay=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{
 for(let i=0;i<40&&!w.MochiReady;i++)await delay(50);
 assert.equal(w.MochiReady,true,'full app becomes ready even while cloud hangs');
 assert.deepEqual(errors,[]);
 assert.equal(w.document.getElementById('qNum').textContent,'Q8','existing local progress is restored before startup');
 assert.equal(JSON.parse(w.localStorage.getItem('mochi-tutor-v1')).coins,42);
 assert.ok(w.document.getElementById('qText').textContent.trim(),'question renders');
 assert.ok(w.document.querySelector('.mochi-watermarks img'),'cat artwork remains');
 assert.ok(w.document.querySelector('#focusSession .learner-avatar img'),'Euna opens her plan from her avatar');
 const dock=w.document.getElementById('focusDock'),lesson=w.document.getElementById('viewMaths');
 assert.equal(dock.parentElement,lesson,'help stays in the lesson document flow');
 assert.ok(w.document.getElementById('problemCard').compareDocumentPosition(dock) & w.Node.DOCUMENT_POSITION_FOLLOWING,'help follows the question');
 assert.equal(w.document.getElementById('mochiFocusHome').closest('#sessionPanel').id,'sessionPanel','schedule lives inside the avatar panel');
 assert.equal(w.document.getElementById('adultBtn').closest('#sessionPanel').id,'sessionPanel','parent settings remain accessible from the avatar');
 assert.deepEqual([...w.document.querySelectorAll('.subject-switch button')].map(n=>n.textContent),['Maths','Science']);
 assert.equal(w.document.getElementById('studyQuestionNote').closest('details').querySelector('summary').textContent,'Why this question?');
 const scripts=requests.filter(x=>x.endsWith('.js'));
 assert.equal(scripts.length,new Set(scripts).size,'no duplicate dynamic script loader');
 const ids=[...w.document.querySelectorAll('[id]')].map(n=>n.id);
 assert.equal(ids.length,new Set(ids).size,'no ambiguous duplicate controls');
 assert.equal(w.document.getElementById('viewCourse').hidden,false,'classroom precedes practice');
 assert.equal(w.document.getElementById('courseCheckStart').disabled,true,'new lesson cannot begin checks yet');
 const click=id=>w.document.getElementById(id).click();
 assert.equal(w.document.getElementById('courseBrowsePractice').closest('details'),null,'original questions have a visible entry');
 click('courseBrowsePractice');
 assert.equal(w.document.getElementById('viewMaths').style.display,'','earlier practice is accessible without clicking through a new textbook');
 assert.equal(w.eval('S.course.lessons["m-number"].completedAt'),0,'opening review does not mark teaching complete');
 click('courseReturn');
 w.document.getElementById('courseNotes').value='I can explain the value of a digit.';
 w.document.getElementById('courseNotes').dispatchEvent(new w.Event('input'));
 for(let i=0;i<7;i++)click('courseNext');
 assert.equal(w.document.getElementById('viewCourse').hidden,true,'finishing the textbook opens original practice directly');
 assert.equal(w.document.getElementById('viewMaths').style.display,'');
 assert.equal(w.eval('learning().session.focusSkill'),'number');
 assert.equal(w.eval('currentSkill()'),'number');
 assert.equal(w.eval('S.course.attempts.length'),0,'short checks have not replaced the original bank');
 const original=w.eval('JSON.stringify({id:studyAttempt.id,question:current.text,session:learning().session})');
 w.document.getElementById('answerInput').value='42';
 w.document.getElementById('typedWorking').value='6 × 7 = 42';
 w.eval('WK.strokes=[[[.1,.2],[.3,.4]]];');
 click('courseReturn');
 assert.equal(w.document.getElementById('courseReading').hidden,false);
 assert.equal(w.document.getElementById('courseNotes').value,'I can explain the value of a digit.');
 click('courseStartPractice');
 assert.equal(w.eval('JSON.stringify({id:studyAttempt.id,question:current.text,session:learning().session})'),original,'book round-trip resumes the same question and session');
 assert.equal(w.document.getElementById('answerInput').value,'42');
 assert.equal(w.document.getElementById('typedWorking').value,'6 × 7 = 42');
 assert.equal(w.eval('WK.strokes.length'),1,'handwriting survives textbook navigation');
 assert.ok(w.eval('studyAttempt.hints')>0,'consulting related teaching counts as support');
 click('courseReturn');
 assert.equal(w.document.getElementById('courseCheckStart').disabled,false);
 w.document.getElementById('courseCheckStart').click();
 let draft=w.eval('S.course.lessons["m-number"].draft');
 const check=w.MochiCourse.question(draft.question);
 assert.equal(w.document.getElementById('courseNotes').value,'','independent check does not display teaching notes');
 w.document.querySelector('[data-choice="'+((check.answer+1)%check.choices.length)+'"]').click();
 w.document.getElementById('courseSubmit').click();
 assert.equal(w.eval('S.course.attempts.at(-1).independent'),false);
 w.document.getElementById('subjectScience').click();
 assert.equal(w.document.getElementById('courseTitle').textContent,'Think and work like a scientist');
 w.document.getElementById('subjectMaths').click();
 assert.equal(w.document.getElementById('courseQuestion').textContent,check.prompt,'unfinished check survives switching subjects');
 w.document.querySelector('[data-choice="'+check.answer+'"]').click();
 w.document.getElementById('courseSubmit').click();
 assert.equal(w.eval('S.course.attempts.length'),1,'revision updates one attempt');
 assert.equal(w.eval('S.course.attempts[0].independent'),false,'revision cannot erase the first miss');
 // Restoring state must not copy the old textarea over the restored notebook.
 w.coursePause();
 w.eval('S.course.lessons["m-number"].notes="Restored notebook";S.course.lessons["m-number"].draft=null;');
 w.courseRefresh();
 assert.equal(w.document.getElementById('courseNotes').value,'Restored notebook');
 const classroomExport=w.MochiReviewDownload.make();
 assert.equal(classroomExport.course.attempts.length,1);
 assert.ok(classroomExport.courseReview.units.some(u=>u.unit==='m-number'&&u.taught));
 w.studioShow('maths');
 w.document.getElementById('answerInput').value='42';
 w.document.getElementById('focusSession').click();
 assert.equal(w.document.getElementById('sessionPanel').hidden,false);
 w.document.getElementById('adultBtn').click();
 assert.ok(w.document.getElementById('ov').classList.contains('show'),'parent settings open');
 w.document.getElementById('ovClose').click();
 assert.equal(w.document.getElementById('answerInput').value,'42','opening plan and parent settings retains the answer');
 assert.ok(w.document.getElementById('qText').textContent.trim());
 w.scShow('science');
 assert.equal(w.document.getElementById('subjectScience').getAttribute('aria-pressed'),'true');
 const question=w.document.getElementById('scQuestion').textContent;
 w.document.querySelector('#scChoices button').click();
 w.document.querySelector('#scConceptChoices button').click();
 w.document.getElementById('scExplanation').value='The path connects both terminals.';
 const experiment=w.document.getElementById('scExperiment');
 assert.equal(experiment.open,false);
 experiment.querySelector('summary').click();
 await delay(40);
 assert.equal(experiment.open,true);
 assert.equal(w.document.getElementById('scQuestion').textContent,question);
 assert.equal(w.document.querySelector('#scChoices button').getAttribute('aria-pressed'),'true');
 w.scShow('maths');
 w.scShow('science');
 assert.equal(w.document.getElementById('scQuestion').textContent,question);
 assert.equal(w.document.getElementById('scExplanation').value,'The path connects both terminals.');
 assert.equal(w.document.querySelector('#scConceptChoices button').getAttribute('aria-pressed'),'true');
 // The Science textbook also hands off to the original illustrated activities.
 w.courseOpen('science','s-electricity');
 for(let i=0;i<7;i++)click('courseNext');
 assert.equal(w.document.getElementById('viewScience').hidden,false);
 assert.equal(w.eval('SCI.skill'),'circuits');
 assert.equal(w.document.getElementById('scTopic').value,'circuits');
 const scienceId=w.eval('SCI.recordId');
 w.document.getElementById('scExplanation').value='Both battery terminals connect in a closed path.';
 w.document.querySelector('#scChoices button').click();
 w.eval('SCI.strokes=[[[.2,.3],[.4,.5]]];');
 click('courseReturn');click('courseStartPractice');
 assert.equal(w.eval('SCI.recordId'),scienceId,'the same Science attempt resumes');
 assert.equal(w.document.getElementById('scExplanation').value,'Both battery terminals connect in a closed path.');
 assert.equal(w.document.querySelector('#scChoices button').getAttribute('aria-pressed'),'true');
 assert.equal(w.eval('SCI.strokes.length'),1);
 assert.equal(w.eval('SCI.helped'),true);
 // A new topic without an old lab uses its own questions, never an unrelated default lab.
 w.courseOpen('science','s-magnets');
 for(let i=0;i<7;i++)click('courseNext');
 assert.equal(w.document.getElementById('viewCourse').hidden,false);
 assert.equal(w.document.getElementById('coursePractice').hidden,false);
 assert.equal(w.eval('S.course.lessons["s-magnets"].draft.question').startsWith('s-magnets'),true);
 click('courseBrowsePractice');
 assert.equal(w.document.getElementById('viewScience').hidden,false,'all original Science questions remain reachable from a new topic');
 assert.equal(w.document.getElementById('scTopic').value,'','all-practice clears the previous topic restriction');
 assert.equal(w.eval('SCI.mode'),'practice','reserved assessment questions stay separate');
 w.courseOpen('maths','m-number');click('courseBrowsePractice');
 assert.equal(w.eval('learning().session.focusSkill'),undefined,'all Maths practice returns to the adaptive mixed bank');
 assert.equal(w.document.getElementById('viewMaths').style.display,'');
 w.scShow('maths');
 w.document.getElementById('inputStylus').click();
 assert.equal(w.document.body.dataset.inputMode,'stylus');
 w.document.getElementById('inputKeyboard').click();
 assert.equal(w.document.body.dataset.inputMode,'keyboard');
 assert.equal(registrations.length,1,'one worker registration after local hydration');
 assert.ok(w.document.getElementById('downloadLearningReview'));
 const beforeReview=JSON.parse(w.localStorage.getItem('mochi-tutor-v1')).learning.attempts.length;
 const exported=w.MochiReviewDownload.make();
 assert.equal(exported.source.appVersion,version);
 assert.equal(exported.learning.attempts.length,beforeReview,'export does not complete an unanswered question');
 assert.equal(exported.review.maths.sampled,0);
 assert.ok(exported.science);
 assert.ok(w.MochiLearning.restore(exported));
 await delay(1300); // Let all bounded setup timers finish.
 let releaseMutations=0;
 const observer=new w.MutationObserver(records=>releaseMutations+=records.length);
 observer.observe(w.document.getElementById('releaseNotes'),{childList:true,subtree:true,characterData:true});
 w.document.dispatchEvent(new w.CustomEvent('mochi:cloud-merged'));
 await delay(1700); // Exercises the former 1.5-second version writer too.
 assert.equal(releaseMutations,0,'version is static, never rewritten by background modules');
 assert.deepEqual([...w.document.querySelectorAll('[data-app-version]')].map(n=>n.textContent),['v'+version,'v'+version]);
 assert.deepEqual(errors,[]);
 observer.disconnect();dom.window.close();
 console.log('Full-page startup, textbook-to-original-practice flow, saved work, input toggle, stable release and stalled-cloud checks passed.');
})().catch(e=>{console.error(e);dom.window.close();process.exitCode=1;});
